const express = require("express");
const fetch = require("node-fetch");
const app = express();

app.use(express.static("public"));

app.get("/", async (req, res) => {
    res.send(indexcode);
})

app.get("/music", async (req, res) => {
    res.send(musicmenucode);
})

app.get("/dino", async (req, res) => {
    res.send(atob(chromedinocodeb64));
})

app.get("/proxy", async (req, res) => {
    let url = req.query.url;
    if (!url) {
        return res.send(proxymenucode);
    };

    if (!/^https?:\/\//i.test(url)) {
        url = "http://" + url;
    }

    try {
        const response = await fetch(url);
        const text = await response.text();
        res.send(text);
    } catch (err) {
        console.error("Error fetching site:", err);
        res.status(500).send("Error fetching site");
    }
});


const server = app.listen(0, () => console.log(`The proxy is running! Navigate to http://localhost:${server.address().port}/ in the RTOS Browser!`));

